"""Reference matching is evidence discovery, never proof of complete anatomy."""
import json,re,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]
GROUPS={
 'nervous': 'brain|cerebellum|pons|medulla oblongata|spinal cord|cervical spinal cord|thoracic spinal cord|lumbar spinal cord|sacral spinal cord|conus medullaris|cauda equina|dorsal root|ventral root|dorsal root ganglion|spinal nerve|cervical plexus|brachial plexus|lumbar plexus|sacral plexus|median nerve|ulnar nerve|radial nerve|musculocutaneous nerve|axillary nerve|femoral nerve|obturator nerve|sciatic nerve|tibial nerve|common fibular nerve|superior gluteal nerve|inferior gluteal nerve|sympathetic trunk|cochlear nerve|vestibular nerve',
 'female':'ovary|uterus|uterine tube|cervix|vagina|clitoris|mammary gland',
 'lymphatic':'spleen|thymus|lymph node|lymphatic vessel|thoracic duct|right lymphatic duct|cisterna chyli|palatine tonsil',
 'endocrine':'thyroid gland|parathyroid gland|pituitary gland|pineal gland|adrenal gland|pancreatic islet|hypothalamus',
 'sensory':'external ear|tympanic membrane|malleus|incus|stapes|cochlea|semicircular canal|vestibule of inner ear|retina|lens',
 'skin':'skin|epidermis|dermis|hypodermis|hair follicle|sebaceous gland|sweat gland'
}
CRANIAL='olfactory|optic|oculomotor|trochlear|trigeminal|abducens|facial|vestibulocochlear|glossopharyngeal|vagus|accessory|hypoglossal'.split('|')
def norm(s): return re.sub(r'^(left|right) ', '',s.lower().strip())
def write(path,data):
 p=R/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
def generate(c,health):
 ss=c['structures']; meshes=c['meshes']; by={s['id']:s for s in ss}
 source='https://training.seer.cancer.gov/anatomy/nervous/organization/pns.html'
 refs=[]
 for group,names in GROUPS.items():
  for name in names.split('|'):
   refs.append(dict(id='REF:'+name.replace(' ','_'),name=name,system=group,cranialNumber=None,ontologyId=None,reviewStatus='PENDING',sourceReferences=[source] if group=='nervous' else []))
 for i,name in enumerate(CRANIAL,1):
  refs.append(dict(id='REF:cranial_'+str(i),name=name+' nerve',system='nervous',cranialNumber=i,ontologyId=None,reviewStatus='PENDING',sourceReferences=[source]))
 write('data/reference/anatomy-reference.json',{'scope':'Initial non-exhaustive editorial checklist; external terminology mapping and expert review pending. Not an ontology export.','structures':refs})
 rows=[]
 for ref in refs:
  exact=[s for s in ss if norm(s['canonicalName'])==ref['name']]
  candidates=[s['id'] for s in ss if ref['name'] in norm(s['canonicalName']) and s not in exact]
  mids=sorted({m for s in exact for m in s['modelAssetIds']})
  rows.append(dict(**ref,conceptIds=[s['id'] for s in exact],candidateConceptIds=candidates,meshIds=mids,conceptExists=bool(exact),meshAvailable=bool(mids),geometryVerified=False,metadataReviewed=False,translationStatus={lang:'DRAFT' if any(s.get(field) for s in exact) else 'MISSING' for lang,field in [('fr','frenchName'),('ar','arabicName'),('la','latinName')]},status='GEOMETRY_UNVERIFIED' if mids else 'RELATED_CANDIDATES' if candidates else 'NO_EXACT_MATCH'))
 report=dict(catalogVersion=c['version'],catalogSha256=hashlib.sha256((R/'public/catalog.json').read_bytes()).hexdigest(),medicalReleaseReady=False,scope='NON_EXHAUSTIVE_REFERENCE',structures=rows)
 write('public/coverage-report.json',report)
 write('docs/reference-coverage.json',report)
 decisions=[]
 for s in ss:
  if s['system']!='other':continue
  represented=sorted({meshes[m]['system'] for m in s['modelAssetIds'] if m in meshes})
  direct=[m for m,v in meshes.items() if v['structureId']==s['id']]
  decisions.append(dict(id=s['id'],name=s['canonicalName'],hasDirectMesh=bool(direct),inheritedMeshIds=s['modelAssetIds'],representedSystems=represented,candidateSystem=None,candidateRegion=None,candidateType='ONTOLOGY_CLASS_REVIEW_REQUIRED',decision='RETAIN_PENDING_REVIEW',reason='No exclusive system inferred from an ontology label. Review source hierarchy and represented systems individually.',confidence=None,sourceReferences=s['sourceReferences'],reviewedBy=None))
 write('data/curation/other-concepts-decisions.json',decisions)
 health['catalogSha256']=report['catalogSha256']
 health['orphanMeshes']=sorted(set(meshes)-{m for s in ss for m in s['modelAssetIds']})
 health['invalidParentRelationships']=[dict(id=s['id'],parent=p) for s in ss for p in s['parentStructure'] if p==s['id'] or p not in by or s['id'] not in by[p]['children']]
 health['initialSceneMeshes']=sum(m['system'] in ['skeletal','muscular'] for m in meshes.values())
 text=['# Reference coverage','', 'Generated by npm run audit:data. Non-exhaustive checklist. Exact names and related-name candidates are not medical validation. Missing exact matches require manual source review; they are not proof of absence. All geometry, text and translations require review.','', '| System | Reference | Exact concepts | Meshes | Related candidates | Status |','|---|---|---:|---:|---:|---|']
 text += [f"| {r['system']} | {r['name']} | {len(r['conceptIds'])} | {len(r['meshIds'])} | {len(r['candidateConceptIds'])} | {r['status']} |" for r in rows]
 (R/'docs/ANATOMY_REFERENCE_COVERAGE.md').write_text('\n'.join(text)+'\n')
 (R/'docs/OTHER_CONCEPTS_AUDIT.md').write_text('# Other concepts review queue\n\nGenerated inventory; individual expert adjudication remains pending. No concepts are reassigned by this report. Per-concept evidence is in data/curation/other-concepts-decisions.json.\n\n| ID | Source name | Direct mesh | Represented systems |\n|---|---|---|---|\n'+'\n'.join(f"| {d['id']} | {d['name']} | {d['hasDirectMesh']} | {', '.join(d['representedSystems'])} |" for d in decisions)+'\n')
 p=R/'docs/PROJECT_STATE.md';state=p.read_text();state=re.sub(r'\n<!-- GENERATED_METRICS -->.*?<!-- END_GENERATED_METRICS -->\n','\n',state,flags=re.S)
 state=state.rstrip()+'\n\n<!-- GENERATED_METRICS -->\n'+f"Current catalogue `{c['version']}`: {len(ss)} concepts; {len(meshes)} meshes; {len(c['packs'])} packs; {health['otherConcepts']} Other concepts; {health['otherMeshes']} Other meshes; {health['systems']['nervous']['meshes']} nervous meshes. Initial scene: {health['initialSceneMeshes']} meshes.\n"+'Generated by npm run audit:data. Counts do not establish anatomical completeness.\n<!-- END_GENERATED_METRICS -->\n';p.write_text(state)
